import { daysSince, formatDate, PlainDate, type YearMonthDay, type YearNumber } from "../common/date";
import { releaseDecade } from "../utils/types";
import { format } from "../utils/mathUtils";
import { earliestYear as earliestYearOf, groupByCategory } from "../common/statsData";
import { platformToShort, type Measure, type VideoGame, type VideoGameStringKeys } from "./types";
import "../utils/arrayUtils";

/**
 * The categories the Top list offers, in the order its select box shows them.
 *
 * The order is load-bearing beyond presentation: `TopList` turns a category's index into a
 * Highcharts palette offset, so reordering this recolours those charts. It lives here rather
 * than being derived from the icon map so that the ordering is a plain value.
 */
export const topOptions = [
  "company",
  "format",
  "franchise",
  "platform",
  "developer",
  "publisher",
  "certificate",
  "status",
  "gameplay",
  "genre",
  "style",
] as const satisfies Exclude<VideoGameStringKeys, "name">[];

export type TopOption = (typeof topOptions)[number];

/**
 * The value a game shows under a grouping, as a word: the charts' own buckets, which the sunburst
 * nests by and the timeline's key names, so a game cannot stand in one bucket on one chart and
 * another beside it. Release decade is a derivation rather than a field — "how much of this is
 * retro?" — and a date is its year.
 */
export const gameGroupValue = (game: VideoGame, key: keyof VideoGame | "decade"): string => {
  if (key === "decade") return releaseDecade(game.releaseDate.year);
  const value = game[key];
  return value instanceof PlainDate ? value.yearString() : String(value);
};

/**
 * Groups completed, time-tracked games by a category, ordered most-played first. The artwork
 * scan is a reduce rather than a sort: only the longest-played game is wanted.
 */
export const groupGamesBy = (data: VideoGame[], key: VideoGameStringKeys, measure: Measure) =>
  groupByCategory(
    data.filter((game) => game.hours && game.endDate),
    (game) => game[key],
    (games) => (measure === "Hours" ? games.sum("hours") : games.length),
    (games) => games.reduce((best, game) => (game.hours! > best.hours! ? game : best)),
  );

/**
 * The first year the library holds a game in, which is the floor the rail's year picker offers. There is
 * no fixed epoch for Games the way Movies has a tracking start date — the sheet's own oldest
 * release is whatever it is — so the floor is read from the data rather than a constant.
 */
export const earliestYear = (data: VideoGame[]): YearNumber => earliestYearOf(data, (game) => game.startDate.year);

/**
 * Every game and the hours logged on them — what both year cards total, scoped by the caller. A
 * game with no hours logged still counts, as it does in the rail's figure and every band beside
 * the cards: counted out here, the card and the bands state two sizes for one library.
 */
export const gamesAndHours = (data: VideoGame[]) => ({
  games: data.length,
  hours: data.filter((game) => game.hours).sum("hours"),
});

/**
 * Games and hours per year, each averaged over the years it has anything in. The games are every
 * game, as the All time card beside this counts them, over the years any game started in; the hours
 * are over the years some game logged time in, so a run of years from before anything was timed
 * does not pull the hours down as years of nothing. Years with neither are absent rather than
 * counted as zero.
 */
export const yearlyAverages = (data: VideoGame[]) => {
  const timed = data.filter((game) => game.hours);
  // Over no year the average is 0 rather than NaN: a page narrowed to nothing still draws the card.
  const yearsOf = (games: VideoGame[]) => new Set(games.map((game) => game.startDate.year)).size || 1;
  return {
    // Whole numbers, as every tab's yearly average states its figures: a year's worth is read
    // against totals in the thousands, and decimals there are precision nobody asked for.
    games: Math.round(data.length / yearsOf(data)),
    hours: Math.floor(timed.sum("hours") / yearsOf(timed)),
  };
};

/**
 * Every game still being played, most recently started first — so the first entry is the one a
 * page leading with a single game should lead with.
 */
export const currentlyPlaying = (data: VideoGame[]) =>
  data.filter((game) => game.status === "Playing").sortByKey("startDate");

/**
 * The figures the hero carries about the game it is showing, in the order every hero states its
 * own: how long it has been in hand, then how much of it there has been.
 *
 * They are the game's own and not the library's: the All Time and in-year cards sit a few hundred
 * pixels below the hero and are the single home of those totals, so repeating them here is one
 * number in two places waiting to disagree. Where it stands in its franchise and its series is the
 * strip's to say, beside the beads it is counted among.
 *
 * Every figure is conditional on the sheet holding what it reports. An in-progress game may have
 * no hours logged yet, and a start typed ahead of today has no days to count — and a tile reading
 * zero says something false in both cases where saying nothing says the truth.
 *
 * `today` is a parameter rather than read from the clock, so the figures are a function of the
 * data alone.
 */
export const heroStats = (game: VideoGame, today: YearMonthDay) => {
  const stats: { label: string; value: number | string }[] = [];

  // Nothing for a start typed ahead of today: there is no day count to show.
  const days = daysSince(game.startDate, today);
  if (days !== undefined) stats.push({ label: "Days In", value: days });

  if (game.hours) stats.push({ label: "Hours", value: game.hours });

  return stats;
};

/** Hours and days-to-beat averaged over games that were actually beaten and timed. */
export const perGameAverages = (data: VideoGame[]) => {
  const filtered = data.filter((game) => game.status === "Beat" && game.hours && game.numDays);
  return {
    hours: Math.round(filtered.sum("hours") / filtered.length),
    days: Math.round(filtered.sum("numDays") / filtered.length),
  };
};

// `hours` is asserted because every caller filters on it first. Dates are in the reader's voice
// and not the machine's, which is the same one the card behind the thumbnail speaks.
export const statsCardLabelEndDateHours = (game: VideoGame) => [
  [game.endDate ? formatDate(game.endDate) : "", `${format(game.hours!)} Hours`],
];

export const statsCardLabelStartDate = (game: VideoGame) => [[formatDate(game.startDate)]];

export const platformToShortChip = (game: VideoGame) => {
  const [label, colour] = platformToShort(game);
  return { label, colour };
};
